mapper.select:
SELECT
FROM fund_financing_plan ffp WHERE ffp.interest_rate_type = 'FLOAT' and exists (select 1 from fund_financing_base_info ffba where ffba.id = ffp.financing_id and ffba.financing_status in ('EFFECT','CARRY_INTEREST') and ffba.approval_status != 'CHANGING_UNDER_APPROVAL'
AND ffba.financing_code = #{financingCode}
)
